}

@property --aurora-angle {
  syntax: '<angle>';
  initial-value: 0deg;
  inherits: false;
}

[data-style='aurora'] .style-fx::before,
[data-style='aurora'] .style-fx::after {
  content: '';
  position: absolute;
  inset: -20%;
  pointer-events: none;
  will-change: transform;
}

[data-style='aurora'] .style-fx::before {
  background:
    radial-gradient(46vw 40vw at 22% 16%, rgba(79, 124, 255, 0.2) 0%, rgba(79, 124, 255, 0) 68%),
    radial-gradient(42vw 38vw at 82% 34%, rgba(139, 92, 246, 0.16) 0%, rgba(139, 92, 246, 0) 70%);
  animation: aurora-mesh-a 42s ease-in-out infinite alternate;
}

[data-style='aurora'] .style-fx::after {
  background:
    radial-gradient(40vw 36vw at 48% 94%, rgba(34, 211, 238, 0.13) 0%, rgba(34, 211, 238, 0) 72%),
    radial-gradient(30vw 26vw at 8% 62%, rgba(79, 124, 255, 0.1) 0%, rgba(79, 124, 255, 0) 74%);
  animation: aurora-mesh-b 54s ease-in-out infinite alternate;
}

:root[data-theme='dark'][data-style='aurora'] .style-fx::before {
  background:
    radial-gradient(46vw 40vw at 22% 16%, rgba(79, 124, 255, 0.26) 0%, rgba(79, 124, 255, 0) 68%),
    radial-gradient(42vw 38vw at 82% 34%, rgba(139, 92, 246, 0.22) 0%, rgba(139, 92, 246, 0) 70%);
}

:root[data-theme='dark'][data-style='aurora'] .style-fx::after {
  background:
    radial-gradient(40vw 36vw at 48% 94%, rgba(34, 211, 238, 0.16) 0%, rgba(34, 211, 238, 0) 72%),
    radial-gradient(30vw 26vw at 8% 62%, rgba(79, 124, 255, 0.14) 0%, rgba(79, 124, 255, 0) 74%);
}

@keyframes aurora-mesh-a {
  0% { transform: translate3d(-2%, -1%, 0) scale(1); }
  50% { transform: translate3d(2.5%, 2%, 0) scale(1.08); }
  100% { transform: translate3d(-1.5%, 1.5%, 0) scale(1.03); }
}

@keyframes aurora-mesh-b {
  0% { transform: translate3d(2%, 1.5%, 0) scale(1.04); }
  50% { transform: translate3d(-3%, -1.5%, 0) scale(1); }
  100% { transform: translate3d(1.5%, -1%, 0) scale(1.06); }
}

[data-style='aurora'] .topbar,
[data-style='aurora'] .search-box {
  background: var(--surface);
  border: 1px solid var(--edge);
  box-shadow: var(--raised-sm);
  backdrop-filter: blur(14px);
  -webkit-backdrop-filter: blur(14px);
}

[data-style='aurora'] .topbar {
  border-radius: 18px;
  padding: 10px 16px;
  position: relative;
}

[data-style='aurora'] .topbar::after {
  content: '';
  position: absolute;
  left: 14px;
  right: 14px;
  bottom: -1px;
  height: 1px;
  background: linear-gradient(90deg, transparent, var(--accent), rgba(139, 92, 246, 0.9), transparent);
  background-size: 200% 100%;
  opacity: 0.75;
  animation: aurora-line 8s linear infinite;
  pointer-events: none;
}

@keyframes aurora-line {
  to { background-position: 200% 0; }
}

[data-style='aurora'] .search-box {
  border-radius: 16px;
}

[data-style='aurora'] .search-box:focus-within {
  border-color: var(--accent);
  box-shadow: 0 0 0 3px var(--accent-soft), 0 0 22px -8px var(--accent-glow);
}

[data-style='aurora'] .card {
  border-radius: 16px;
  background: var(--surface);
  border: 1px solid var(--edge);
  box-shadow: var(--raised-sm);
  isolation: isolate;
  transition: transform 220ms var(--ease), box-shadow 220ms var(--ease), border-color 220ms var(--ease);
}

[data-style='aurora'] .card::after {
  content: '';
  position: absolute;
  inset: 0;
  z-index: -1;
  border-radius: inherit;
  background: radial-gradient(300px 230px at var(--px, 50%) var(--py, 0%), rgba(79, 124, 255, 0.26) 0%, rgba(139, 92, 246, 0.16) 42%, rgba(34, 211, 238, 0) 72%);
  opacity: 0;
  transition: opacity 280ms var(--ease);
  pointer-events: none;
}

[data-style='aurora'] .card::before {
  content: '';
  position: absolute;
  inset: -1px;
  z-index: 2;
  border-radius: inherit;
  padding: 1.5px;
  background: conic-gradient(from var(--aurora-angle), rgba(79, 124, 255, 0), rgba(79, 124, 255, 0.95), rgba(139, 92, 246, 0.95), rgba(34, 211, 238, 0.9), rgba(79, 124, 255, 0));
  -webkit-mask: linear-gradient(#000 0 0) content-box, linear-gradient(#000 0 0);
  -webkit-mask-composite: xor;
  mask: linear-gradient(#000 0 0) content-box, linear-gradient(#000 0 0);
  mask-composite: exclude;
  opacity: 0;
  transition: opacity 240ms var(--ease);
  pointer-events: none;
}

[data-style='aurora'] .card:hover {
  transform: translateY(-3px);
  border-color: transparent;
  box-shadow: var(--raised-lg), 0 0 26px -10px var(--accent-glow);
}

[data-style='aurora'] .card:hover::before {
  opacity: 1;
  animation: aurora-spin 4s linear infinite;
}

[data-style='aurora'] .card:hover::after {
  opacity: 1;
}

[data-style='aurora'] .card:active {
  transform: translateY(0) scale(0.99);
  box-shadow: var(--pressed-sm);
}

@keyframes aurora-spin {
  to { --aurora-angle: 360deg; }
}

[data-style='aurora'] .card .icon {
  border-radius: 12px;
}

[data-style='aurora'] .group,
[data-style='aurora'] .group-parent {
  background: transparent;
  border: 1px solid var(--edge-weak);
  border-radius: 20px;
  box-shadow: none;
}

[data-style='aurora'] .group:hover,
[data-style='aurora'] .group-parent:hover {
  transform: none;
  box-shadow: none;
}

[data-style='aurora'] .group-parent-head {
  background: transparent;
  border: none;
  box-shadow: none;
  padding-left: 0;
}

[data-style='aurora'] .group-parent-head:hover {
  transform: none;
  box-shadow: none;
}

[data-style='aurora'] .group-parent-head h3 {
  background: none;
  -webkit-text-fill-color: currentColor;
  color: var(--text);
}

[data-style='aurora'] .group-child {
  background: transparent;
  border: none;
  border-left: 2px solid var(--accent);
  border-radius: 14px;
  box-shadow: none;
}

[data-style='aurora'] .clock-time {
  background: linear-gradient(100deg, var(--accent), #a78bfa, #22d3ee, var(--accent));
  background-size: 300% 100%;
  -webkit-background-clip: text;
  background-clip: text;
  -webkit-text-fill-color: transparent;
  color: transparent;
  text-shadow: none;
  filter: drop-shadow(0 0 22px var(--accent-glow));
  animation: aurora-text 10s linear infinite;
}

@keyframes aurora-text {
  to { background-position: 300% 0; }
}

[data-style='aurora'] .btn-primary,
[data-style='aurora'] .search-box .search-btn {
  background-image: linear-gradient(110deg, var(--accent), #8b5cf6, var(--accent));
  background-size: 200% 100%;
  animation: aurora-sheen 6s linear infinite;
  box-shadow: 0 6px 18px -8px var(--accent-glow);
}

@keyframes aurora-sheen {
  to { background-position: 200% 0; }
}

[data-style='aurora'] .btn:hover {
  transform: translateY(-1px);
  box-shadow: var(--raised), 0 0 18px -8px var(--accent-glow);
}

[data-style='aurora'] .btn:active {
  transform: scale(0.98);
}

[data-style='aurora'] .icon-btn:hover {
  transform: translateY(-1px);
  color: var(--accent);
  box-shadow: 0 0 16px -8px var(--accent-glow);
}

[data-style='aurora'] .nm-item.active .nm-face {
  background: linear-gradient(135deg, var(--accent), #8b5cf6);
  border-color: transparent;
}

[data-style='aurora'] .group-nav,
[data-style='aurora'] .engine-menu,
[data-style='aurora'] .search-history-dropdown,
[data-style='aurora'] .card-context-menu,
[data-style='aurora'] .modal-box,
[data-style='aurora'] .toast {
  border-radius: 16px;
  backdrop-filter: blur(14px);
  -webkit-backdrop-filter: blur(14px);
}

[data-style='aurora'] .card:focus-visible,
[data-style='aurora'] .btn:focus-visible,
[data-style='aurora'] .icon-btn:focus-visible {
  box-shadow: 0 0 0 3px var(--accent-soft);
}

@media (prefers-reduced-motion: reduce) {
  [data-style='aurora'] *,
  [data-style='aurora'] *::before,
  [data-style='aurora'] *::after {
    animation: none !important;
    transition-duration: 1ms !important;
  }
}

